'use strict';
const icons={settings:'<path d="m9 3-1 3-3 1v4l3 1 1 3h4l1-3 3-1V7l-3-1-1-3Z" transform="translate(1 2)"/><circle cx="12" cy="11" r="3"/>',camera:'<path d="M14 4h-4L8 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-4Z"/><circle cx="12" cy="13" r="3"/>',route:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M7 5h8a4 4 0 0 1 0 8H9a4 4 0 0 0 0 8h8"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',battery:'<rect x="2" y="7" width="17" height="10" rx="2"/><path d="M22 10v4m-16-3v2m4-2v2m4-2v2"/>',gauge:'<path d="M4 18a9 9 0 1 1 16 0"/><path d="m12 13 4-5"/><circle cx="12" cy="13" r="1"/>',signal:'<path d="M3 19v-3m6 3v-7m6 7V8m6 11V4"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',gamepad:'<path d="M7 7h10a4 4 0 0 1 4 3l1 7a2 2 0 0 1-3 2l-4-3H9l-4 3a2 2 0 0 1-3-2l1-7a4 4 0 0 1 4-3Z"/><path d="M6 11h4m-2-2v4m8-2h.1m2 2h.1"/>',sparkles:'<path d="m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7ZM20 2v4m-2-2h4"/>','chevron-right':'<path d="m9 5 7 7-7 7"/>','chevron-left':'<path d="m15 5-7 7 7 7"/>','chevron-up':'<path d="m5 15 7-7 7 7"/>','chevron-down':'<path d="m5 9 7 7 7-7"/>','arrow-up':'<path d="M12 20V4m-6 6 6-6 6 6"/>','arrow-up-right':'<path d="M6 18 18 6M6 6h12v12"/>','turn-left':'<path d="m9 3-6 6 6 6M3 9h10a7 7 0 0 1 7 7v5"/>',stop:'<rect x="6" y="6" width="12" height="12" rx="2"/>',play:'<path d="m8 4 12 8-12 8Z"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-5"/>',octagon:'<path d="m8 2-6 6v8l6 6h8l6-6V8l-6-6Z"/><path d="M9 9h6v6H9Z"/>',refresh:'<path d="M20 8a8 8 0 1 0 0 8M20 3v5h-5"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>','wifi-off':'<path d="m3 3 18 18M2 8a16 16 0 0 1 4-2m4-1a16 16 0 0 1 12 3M5 12a11 11 0 0 1 5-2m5 1 4 1M8 16a6 6 0 0 1 8 0m-4 4h.01"/>'};
function paintIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[el.dataset.icon]||icons.info}</svg>`;});}
paintIcons();
const $=id=>document.getElementById(id);
const physics=window.RoverPhysics;
let car=physics.createState();
const state={connected:true,mode:'manual',speedLimit:30,wet:false,estop:false,serviceBrake:0,failsafe:false,plan:null,controls:new Map(),logs:[],trail:[[0,0]],latency:null,map:false,started:performance.now(),brakeAnchor:null,collision:false,lastInput:{throttle:0,brake:0,steering:0},predicted:0,pausedAt:null};
let camera=null,cameraReady=false,lastFrame=performance.now(),lastRender=0,lastCameraFrame=0,toastTimer;
const driveNames={throttle:'油门',brake:'刹车',left:'左转向',right:'右转向'};
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3000);}
function log(message){state.logs.unshift({time:new Date().toLocaleTimeString('zh-CN',{hour12:false}),message});state.logs=state.logs.slice(0,80);renderLogs();}
function renderLogs(){const list=$('activity-log');list.replaceChildren();for(const entry of state.logs){const li=document.createElement('li'),time=document.createElement('time'),text=document.createElement('span');time.textContent=entry.time;text.textContent=entry.message;li.append(time,text);list.append(li);}}
function cancelPlan(reason){if(state.plan&&['running','ready'].includes(state.plan.status)){state.plan.status='cancelled';state.plan.reason=reason;renderPlan();}}
function requestBrake(reason,amount=.55,{emergency=false}={}){state.controls.clear();cancelPlan(reason);state.serviceBrake=Math.max(state.serviceBrake,amount);if(emergency)state.estop=true;log(reason);render();}
function emergencyStop(){requestBrake('紧急制动：全力刹车，车辆仍将继续前进直至停止',1,{emergency:true});toast('正在全力制动，刹车距离会持续累计');}
function releaseEmergency(){if(car.speed>.01)return;state.estop=false;state.failsafe=false;state.serviceBrake=0;state.collision=false;log('制动锁定已解除，车辆保持静止');render();}
function available(){if(state.estop){toast('请等车辆停稳后解除制动锁定');return false;}if(!state.connected||!cameraReady){toast('连接或画面不可用，保持制动');return false;}if(car.energyKWh>=51.6){toast('模拟电量耗尽，请重置模拟');return false;}return true;}
function switchMode(mode){if(!['manual','ai'].includes(mode))return;if(mode!==state.mode){state.controls.clear();if(state.plan?.status==='running')requestBrake('已切换控制方式，取消 AI 并开始常规制动');state.mode=mode;}for(const name of ['manual','ai']){const active=name===mode;$(name+'-panel').hidden=!active;$(name+'-tab').classList.toggle('active',active);$(name+'-tab').setAttribute('aria-selected',String(active));$(name+'-tab').tabIndex=active?0:-1;}render();}
$('manual-tab').onclick=()=>switchMode('manual');$('ai-tab').onclick=()=>switchMode('ai');$('ai-shortcut').onclick=()=>{switchMode('ai');$('ai-tab').scrollIntoView({block:'nearest',behavior:'smooth'});};
for(const mode of ['manual','ai'])$(mode+'-tab').onkeydown=event=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const next=event.key==='Home'?'manual':event.key==='End'?'ai':mode==='manual'?'ai':'manual';switchMode(next);$(next+'-tab').focus();}};
function pressDrive(action,id){if(state.controls.has(id)||!available())return false;cancelPlan('手动接管');state.failsafe=false;state.controls.set(id,action);if(action==='throttle'){state.serviceBrake=0;}log(`手动操作：${driveNames[action]}`);render();return true;}
function releaseDrive(id,cancelled=false){const action=state.controls.get(id);if(!action)return;state.controls.delete(id);if(cancelled)requestBrake('触控中断，开始常规制动');else if(action==='throttle')log('松开油门，车辆按阻力自然滑行');render();}
document.querySelectorAll('[data-drive]').forEach(button=>{
  button.onpointerdown=event=>{if(event.button!==0)return;event.preventDefault();const id='p'+event.pointerId;if(!pressDrive(button.dataset.drive,id))return;try{button.setPointerCapture(event.pointerId);}catch{releaseDrive(id,true);}};
  button.onpointerup=event=>releaseDrive('p'+event.pointerId);
  button.onpointercancel=event=>releaseDrive('p'+event.pointerId,true);
  button.onlostpointercapture=event=>releaseDrive('p'+event.pointerId,true);
  button.oncontextmenu=event=>event.preventDefault();
  button.onkeydown=event=>{if(['Enter',' '].includes(event.key)){event.preventDefault();if(!event.repeat)pressDrive(button.dataset.drive,'k'+event.code);}};
});
window.addEventListener('pointerup',event=>releaseDrive('p'+event.pointerId));
window.addEventListener('pointercancel',event=>releaseDrive('p'+event.pointerId,true));
const keyMap={ArrowUp:'throttle',KeyW:'throttle',ArrowDown:'brake',KeyS:'brake',ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right'};
window.addEventListener('keydown',event=>{if(event.defaultPrevented||event.target.closest?.('input,textarea,select,[contenteditable="true"]')||document.querySelector('dialog[open]'))return;if(event.code==='Space'){event.preventDefault();requestBrake('按下空格，常规制动至停止');return;}if(event.key==='Escape'){requestBrake('已请求常规制动');if($('camera-panel').classList.contains('expanded'))toggleExpand(false);return;}if(state.mode!=='manual'||!keyMap[event.code])return;event.preventDefault();if(!event.repeat)pressDrive(keyMap[event.code],'k'+event.code);});
window.addEventListener('keyup',event=>releaseDrive('k'+event.code));
function failSafe(reason){state.failsafe=true;requestBrake(reason,1);}
window.addEventListener('blur',()=>{if(car.speed>.01||state.controls.size||state.plan?.status==='running')failSafe('页面失去焦点，接管为全力制动');});
document.addEventListener('visibilitychange',()=>{if(document.hidden){state.pausedAt=performance.now();failSafe('页面进入后台，自动制动已触发');camera?.pause();}else{const elapsed=state.pausedAt===null?0:(performance.now()-state.pausedAt)/1000;advanceElapsed(Math.min(elapsed,60),true);state.pausedAt=null;lastFrame=performance.now();lastCameraFrame=0;render();}});
window.addEventListener('pagehide',()=>{state.controls.clear();state.failsafe=true;cancelPlan('页面离开');});
$('normal-stop').onclick=()=>requestBrake('常规制动：持续刹车至完全停止');$('emergency-stop').onclick=emergencyStop;$('reset-estop').onclick=releaseEmergency;
$('speed-slider').oninput=event=>{const value=Number(event.target.value);if(!Number.isFinite(value)||value<1||value>100)return;state.speedLimit=value;event.target.style.setProperty('--speed-progress',((value-1)/99*100)+'%');render();};
function setRoad(wet){if(car.braking){toast('请在本次制动结束后切换路面');return;}state.wet=wet;state.brakeAnchor=null;log(`路面切换为${wet?'湿滑':'干燥'}，摩擦系数 ${wet?.45:.85}`);render();}
$('dry-road').onclick=()=>setRoad(false);$('wet-road').onclick=()=>setRoad(true);
function chineseNumbers(text){const digits={零:0,一:1,二:2,两:2,三:3,四:4,五:5,六:6,七:7,八:8,九:9};return text.replace(/[零一二两三四五六七八九十百]+/g,word=>{let sum=0,current=0;for(const char of word){if(char==='百'||char==='十'){sum+=(current||1)*(char==='百'?100:10);current=0;}else current=digits[char];}return String(sum+current);});}
function parseCommand(raw){if(typeof raw!=='string'||!raw.trim()||raw.length>120)throw new Error('请输入 1～120 字的指令。');const text=chineseNumbers(raw.trim().replace(/\s+/g,'').replace(/[，,。！!]/g,''));if(/^(急停|紧急停车|紧急制动|紧急刹车)$/.test(text))return {emergency:true};if(/^(刹车|刹车停止|停止|停止移动|停车|停下|停止任务|停止执行)$/.test(text))return {stop:true};if(/^(制动测试|刹车测试)$/.test(text))return brakingTest(state.speedLimit,raw);let match=text.match(/^(?:加速(?:到|至)?|以)?(\d+(?:\.\d+)?)(?:米每秒|m\/s)(?:(?:然后|后|再)?(?:刹车|制动|停车|制动测试))$/i);if(match)return brakingTest(Number(match[1]),raw);match=text.match(/^(?:向前走|前进|行驶|向前)(\d+(?:\.\d+)?)(?:米|m)$/i);if(match){const distance=Number(match[1]);if(distance<1||distance>5000)throw new Error('高速场景支持 1～5000 米的前进任务。');return {kind:'drive',target:state.speedLimit,distance,title:raw,labels:[`行驶 ${distance} 米`,`随后全力制动（仍会前进）`]};}throw new Error('试试“加速到 50 米每秒然后刹车”或“前进 200 米”。');}
function brakingTest(target,title){if(!Number.isFinite(target)||target<1||target>100)throw new Error('速度必须在 1～100 m/s 之间。');return {kind:'brake-test',target,title,labels:[`调整车速至 ${target} m/s（${Math.round(target*3.6)} km/h）`,'全力制动，测量实际刹车距离']};}
function submitCommand(raw){try{const parsed=parseCommand(raw);if(parsed.emergency){emergencyStop();return {status:'braking'};}if(parsed.stop){requestBrake('AI 指令请求常规制动至停止');$('ai-feedback').textContent='已经踩下刹车，速度和实际制动距离仍会继续变化，直至停车。';return {status:'braking'};}if(!available())return {status:'blocked'};if(state.plan?.status==='running')requestBrake('新计划替换旧任务，先开始制动');state.plan={...parsed,status:'ready',phase:0,startDistance:car.distance,brakeStartDistance:0};$('ai-feedback').textContent='请确认计划。加速和制动都按物理过程执行，车速不会瞬间改变。';$('ai-feedback').classList.remove('error');log(`生成计划：${parsed.title}`);renderPlan();return {status:'ready',steps:parsed.labels};}catch(error){$('ai-feedback').textContent=error.message;$('ai-feedback').classList.add('error');return {status:'error',message:error.message};}}
$('command-form').onsubmit=event=>{event.preventDefault();submitCommand($('command-input').value);};$('command-input').onkeydown=event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();submitCommand(event.target.value);}};
document.querySelectorAll('[data-command]').forEach(button=>button.onclick=()=>{$('command-input').value=button.dataset.command;submitCommand(button.dataset.command);});
function startPlan(){if(state.plan?.status!=='ready'||!available())return false;state.controls.clear();state.serviceBrake=0;state.failsafe=false;state.brakeAnchor=null;state.plan.status='running';state.plan.phase=0;state.plan.startDistance=car.distance;state.speedLimit=state.plan.target;$('speed-slider').value=String(state.speedLimit);$('speed-slider').style.setProperty('--speed-progress',((state.speedLimit-1)/99*100)+'%');log(`AI 开始执行：${state.plan.title}`);renderPlan();render();return true;}
$('task-action').onclick=()=>{if(state.plan?.status==='ready')startPlan();else if(state.plan?.status==='running')requestBrake('停止 AI 任务，持续常规制动');else{state.plan=null;renderPlan();}};
function renderPlan(){const plan=state.plan;$('task-card').hidden=!plan;if(!plan)return;const status={ready:'待确认',running:plan.phase?'制动中':'执行中',completed:'已完成',cancelled:car.speed>.01?'已取消 · 制动中':'已取消'};$('task-badge').textContent=status[plan.status];$('task-steps').replaceChildren();plan.labels.forEach((label,index)=>{const li=document.createElement('li'),number=document.createElement('span'),text=document.createElement('span');number.className='step-number';const done=plan.status==='completed'||index<plan.phase;number.textContent=done?'✓':String(index+1);text.textContent=label;li.className=done?'done':plan.status==='running'&&index===plan.phase?'current':'';li.append(number,text);$('task-steps').append(li);});const action=$('task-action');action.replaceChildren();const icon=document.createElement('i'),text=document.createElement('span');icon.dataset.icon=plan.status==='running'?'stop':plan.status==='ready'?'play':'refresh';text.textContent=plan.status==='running'?'取消并制动':plan.status==='ready'?'开始执行':'新的任务';action.append(icon,text);paintIcons(action);}
function updatePlan(){const plan=state.plan;if(plan?.status!=='running')return;if(plan.phase===0){const reached=plan.kind==='brake-test'?Math.abs(car.speed-plan.target)<.01:car.distance-plan.startDistance>=plan.distance;if(reached){plan.phase=1;plan.brakeStartDistance=car.distance;car.braking=false;state.brakeAnchor=null;log(`达到阶段目标，开始全力制动；初速 ${car.speed.toFixed(2)} m/s`);renderPlan();}}else if(car.speed<.0001){plan.status='completed';state.serviceBrake=0;log(`AI 制动完成：实际刹车距离 ${(car.lastBrakeDistance||0).toFixed(2)} m`);$('ai-feedback').textContent=`已完全停车。实际制动距离 ${(car.lastBrakeDistance||0).toFixed(2)} 米，车辆按物理过程减速。`;toast('测试完成，实际刹车距离已保留');renderPlan();}}
function getInput(){const values=[...state.controls.values()];let throttle=values.includes('throttle')?1:0,brake=values.includes('brake')?.55:state.serviceBrake,steering=(values.includes('right')?1:0)-(values.includes('left')?1:0);const plan=state.plan;if(plan?.status==='running'){steering=0;if(plan.phase===1){throttle=0;brake=1;}else{throttle=car.speed<=plan.target?1:0;brake=car.speed>plan.target+.12?.35:0;}}if(state.estop||state.failsafe||!state.connected||!cameraReady||car.energyKWh>=51.6){throttle=0;brake=1;steering=0;}if(brake>0)throttle=0;return {throttle,brake,steering,targetSpeed:Math.min(100,state.plan?.status==='running'?state.plan.target:state.speedLimit),wet:state.wet};}
function advance(dt){updatePlan();const input=getInput();state.lastInput=input;if(input.brake>0&&car.speed>0&&(!car.braking||state.brakeAnchor?.pressure!==input.brake)){state.brakeAnchor={x:car.x,y:car.y,heading:car.heading,pressure:input.brake,distance:physics.estimateBrakingDistance(car.speed,{wet:state.wet,brake:input.brake})};}else if(input.brake===0&&car.braking)state.brakeAnchor=null;const oldX=car.x,oldY=car.y,oldDistance=car.distance,wasBraking=car.braking;physics.step(car,input,dt);
  const rail=6.45;if(Math.abs(car.x)>rail){const collidedX=car.x;car.x=Math.max(-rail,Math.min(rail,car.x));const h=car.heading*Math.PI/180,vx=-Math.sin(h)*car.speed*.05,vz=Math.cos(h)*car.speed*.88;car.speed=Math.hypot(vx,vz);car.heading=(Math.atan2(vx,vz)*180/Math.PI+360)%360;const accepted=Math.hypot(car.x-oldX,car.y-oldY);car.distance=oldDistance+accepted;if(car.braking)car.brakeDistance=Math.max(0,car.brakeDistance-(Math.hypot(collidedX-oldX,car.y-oldY)-accepted));if(!state.collision){state.collision=true;requestBrake('护栏碰撞：采用非弹性碰撞响应，并继续全力制动',1,{emergency:true});}}
  const prev=state.trail[state.trail.length-1];if(Math.hypot(car.x-prev[0],car.y-prev[1])>.5){state.trail.push([car.x,car.y]);if(state.trail.length>1500)state.trail.splice(1,1);}if(wasBraking&&!car.braking&&car.speed===0){log(`车辆已停稳，制动距离 ${(car.lastBrakeDistance||0).toFixed(2)} m`);if(!state.estop&&!state.failsafe)state.serviceBrake=0;renderPlan();}updatePlan();}
function advanceElapsed(elapsed,background=false){let remaining=Math.max(0,elapsed);while(remaining>0){const step=Math.min(remaining,1/120);advance(step);remaining-=step;if(background&&car.speed===0)break;}}
function openSheet(id){requestBrake('打开信息面板，开始常规制动');$(id).showModal();}
$('device-button').onclick=()=>openSheet('device-dialog');$('log-button').onclick=()=>openSheet('log-dialog');document.querySelectorAll('[data-close]').forEach(button=>button.onclick=()=>$(button.dataset.close).close());document.querySelectorAll('dialog').forEach(dialog=>dialog.onclick=event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();});
$('toggle-connection').onclick=()=>{state.connected=!state.connected;failSafe(state.connected?'连接已恢复，车辆继续制动至停止':'模拟连接断开，触发全力制动');camera?.pause();render();};
function resetSession(){const keepLocked=state.estop;car=physics.createState();Object.assign(state,{estop:keepLocked,serviceBrake:0,failsafe:false,plan:null,trail:[[0,0]],logs:[],started:performance.now(),brakeAnchor:null,collision:false});state.controls.clear();$('command-input').value='';$('ai-feedback').textContent='支持制动测试、定距前进和刹车停止，速度上限 100 m/s。';$('ai-feedback').classList.remove('error');log('模拟已重置，车辆回到起点');renderPlan();render();}
$('reset-session').onclick=()=>{resetSession();$('device-dialog').close();};
$('view-switch').onclick=()=>{state.map=!state.map;camera?.pause();$('map-view').hidden=!state.map;$('view-title').textContent=state.map?'行驶轨迹':'高速公路 · 驾驶视角';$('view-switch').querySelector('span').textContent=state.map?'画面':'轨迹';$('view-switch').setAttribute('aria-label',state.map?'切换到驾驶画面':'切换到行驶轨迹');render();};
function toggleExpand(force){const expanded=force??!$('camera-panel').classList.contains('expanded');$('camera-panel').classList.toggle('expanded',expanded);$('expand-button').setAttribute('aria-label',expanded?'缩小画面':'放大画面');$('expand-button').setAttribute('aria-expanded',String(expanded));document.body.style.overflow=expanded?'hidden':'';}
$('expand-button').onclick=()=>toggleExpand();
function render(){const moving=car.speed>.01,braking=state.lastInput.brake>0&&moving;state.predicted=physics.estimateBrakingDistance(car.speed,{wet:state.wet,brake:1});$('speed-value').textContent=car.speed.toFixed(1);$('speed-kmh').textContent=(car.speed*3.6).toFixed(1)+' km/h';$('predicted-brake').textContent=state.predicted.toFixed(1);$('actual-brake').textContent=car.braking?car.brakeDistance.toFixed(1):car.lastBrakeDistance===null?'—':car.lastBrakeDistance.toFixed(1);$('actual-brake-label').textContent=car.braking?'正在制动':'上次制动';$('brake-result-label').textContent=car.braking?'距离正在累计':'停车后保留实测结果';$('braking-hud').hidden=!braking;$('braking-hud-distance').textContent=car.brakeDistance.toFixed(1)+' m';$('braking-hud-label').textContent=state.estop?'紧急制动':state.lastInput.brake>=1?'全力制动':'常规制动';$('speed-limit-label').textContent=String(state.speedLimit);$('target-kmh').textContent=(state.speedLimit*3.6).toFixed(0)+' km/h';$('odometer-live').textContent=car.distance.toFixed(1)+' m';$('distance-value').textContent=car.distance.toFixed(1);$('map-distance').textContent=car.distance.toFixed(1)+' m';$('heading-live').textContent=(Math.round(car.heading)%360)+'°';$('acceleration-live').textContent=car.acceleration.toFixed(2)+' m/s²';$('position-text').textContent=`X ${car.x.toFixed(1)} · Y ${car.y.toFixed(1)} m`;$('heading-text').textContent=String(Math.round(car.heading)%360).padStart(3,'0')+'°';$('steering-angle').textContent=(car.steer*180/Math.PI).toFixed(1)+'°';$('steering-indicator').style.transform=`rotate(${car.steer*180/Math.PI*3}deg)`;
  const drivingLabel=braking?'正在制动，车辆仍在前进':moving?(state.lastInput.throttle?'正在加速 / 巡航':'松开油门，惯性滑行'):'车辆已停稳';$('camera-mode').textContent=(state.plan?.status==='running'?'AI 试驾':'手动驾驶')+' · '+(state.wet?'湿滑路面':'干燥路面');$('camera-status').textContent=drivingLabel;$('safety-title').textContent=state.estop?(moving?'紧急制动中':'已停稳 · 制动锁定'):drivingLabel;$('safety-description').textContent=state.estop?(moving?`已制动 ${car.brakeDistance.toFixed(1)} m`:'解除后不会自动行驶'):moving?`${car.speed.toFixed(1)} m/s · ${braking?'持续减速':'注意刹车距离'}`:'按住油门开始驾驶';document.querySelector('.safety-bar').classList.toggle('stopped',state.estop);$('emergency-stop').hidden=state.estop;$('reset-estop').hidden=!state.estop;$('reset-estop').disabled=moving;$('reset-estop').textContent=moving?'制动中，等待停稳':'解除制动锁定';$('connection-dot').classList.toggle('offline',!state.connected);$('connection-label').textContent=state.connected?'模拟连接正常':'失联，自动制动';$('camera-offline').hidden=state.connected;$('device-status').textContent=state.connected?'模拟连接正常':'已断开，制动中';$('toggle-connection').textContent=state.connected?'断开模拟连接':'恢复模拟连接';$('dry-road').classList.toggle('selected',!state.wet);$('dry-road').setAttribute('aria-pressed',String(!state.wet));$('wet-road').classList.toggle('selected',state.wet);$('wet-road').setAttribute('aria-pressed',String(state.wet));$('dry-road').disabled=car.braking;$('wet-road').disabled=car.braking;$('grip-value').textContent=state.wet?'μ 0.45':'μ 0.85';$('device-grip').textContent=state.wet?'0.45（湿滑）':'0.85（干燥）';$('device-rtt').textContent=state.latency===null?'未测量 / 不可达':state.latency.toFixed(1)+' ms';$('device-power').textContent=Math.max(0,86-car.energyKWh/60*100).toFixed(1)+'% / '+((car.powerW||0)/1000).toFixed(1)+' kW';
  for(const button of document.querySelectorAll('[data-drive]')){button.classList.toggle('active',[...state.controls.values()].includes(button.dataset.drive));button.disabled=state.estop||!state.connected||!cameraReady;}const fps=state.connected&&!state.map?camera?.stats.fps:0;$('frame-rate').textContent=state.connected?`${fps||'—'} FPS`:'PAUSED';$('device-fps').textContent=fps?`${fps} FPS · ${camera.stats.backend}`:'画面暂停 / 测量中';const seconds=Math.floor((performance.now()-state.started)/1000);$('session-clock').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');if(state.plan){$('task-action').disabled=state.plan.status==='ready'&&(state.estop||!state.connected||!cameraReady);let progress=state.plan.status==='completed'?1:state.plan.phase? .5+.5*(1-car.speed/Math.max(1,car.brakeStartSpeed)):state.plan.kind==='brake-test'?.5*Math.min(1,car.speed/state.plan.target):.5*Math.min(1,(car.distance-state.plan.startDistance)/state.plan.distance);$('task-progress-fill').style.width=Math.max(0,Math.min(100,progress*100))+'%';}
  if(state.map){const scale=.5,latest=car.y;const originY=260+latest*scale;$('map-origin').setAttribute('transform',`translate(320 ${originY})`);$('map-origin').style.display=originY>=0&&originY<=330?'':'none';$('route-trail').setAttribute('points',state.trail.filter(p=>p[1]>latest-480&&p[1]<latest+160).map(([x,y])=>`${320+x*8},${260-(y-latest)*scale}`).join(' '));$('map-rover').setAttribute('transform',`translate(${320+car.x*8} 260) rotate(${car.heading})`);}
}
function tick(now){if(!document.hidden){const elapsed=(now-lastFrame)/1000;lastFrame=now;if(elapsed>.5){if(car.speed>.01||state.controls.size||state.plan?.status==='running')failSafe('画面发生长时间停顿，自动接管制动');camera?.pause();}advanceElapsed(Math.min(Math.max(0,elapsed),60));const interval=1000/30;if(cameraReady&&state.connected&&!state.map&&now-lastCameraFrame>=interval){lastCameraFrame=now-((now-lastCameraFrame)%interval);const pose={...car,wet:state.wet,brakePrediction:state.predicted,brakeAnchor:state.brakeAnchor};if(camera.draw(pose,now)){$('camera-canvas').dataset.frame=String(camera.stats.frames);const seconds=(now-state.started)/1000;$('camera-live-clock').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+(seconds%60).toFixed(1).padStart(4,'0');}}if(now-lastRender>100){render();lastRender=now;}}requestAnimationFrame(tick);}
try{camera=window.RoverSimulator.createCamera($('camera-canvas'));cameraReady=true;}catch(error){$('camera-error').hidden=false;console.error(error);}
window.addEventListener('rover-camera-lost',()=>{cameraReady=false;failSafe('画面丢失，继续全力制动');$('camera-error').hidden=false;});
async function probeLocalService(){if(document.hidden){setTimeout(probeLocalService,2000);return;}const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),2000),started=performance.now();try{const response=await fetch('/health.json?t='+Math.floor(started),{method:'HEAD',cache:'no-store',signal:controller.signal});if(!response.ok)throw new Error();state.latency=performance.now()-started;}catch{state.latency=null;}finally{clearTimeout(timer);setTimeout(probeLocalService,2000);}}
function readState(){return {simulation:true,scenario:'highway',model:'simplified vehicle dynamics',connected:state.connected,emergencyBrake:state.estop,speed:car.speed,maxSpeed:100,targetSpeed:state.speedLimit,acceleration:car.acceleration,position:{x:car.x,y:car.y,heading:car.heading},distance:car.distance,braking:car.braking,brakeDistance:car.brakeDistance,lastBrakeDistance:car.lastBrakeDistance,predictedBrakingDistance:state.predicted,wet:state.wet,taskStatus:state.plan?.status||'none',cameraFps:camera?.stats.fps||0,localLatencyMs:state.latency};}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const definitions=[{name:'read_rover_simulation',title:'查看车辆物理模拟状态',description:'Read local highway physics, actual speed and physical braking distance. No real hardware.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:readState},{name:'stage_rover_simulation_command',title:'准备高速模拟任务',description:'Stage a local highway simulation plan for confirmation. Brake commands apply deceleration immediately; they do not teleport speed to zero.',inputSchema:{type:'object',properties:{command:{type:'string',minLength:1,maxLength:120}},required:['command'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.command!=='string')throw new Error('command required');switchMode('ai');$('command-input').value=input.command;return submitCommand(input.command);}},{name:'emergency_stop_rover_simulation',title:'全力制动模拟车辆',description:'Latch full emergency brakes in the local simulation. Speed decreases physically over a nonzero braking distance. Does not immediately stop or control real hardware.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(){emergencyStop();return readState();}}];for(const tool of definitions){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
log('高速公路物理模拟就绪，上限 100 m/s');render();requestAnimationFrame(tick);probeLocalService();
